74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    private final HouseholdDuplicateValidator householdDuplicateValidator;
88	
89	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
90	
91	    private final NamesakeCounter namesakeCounter;
92	
93	    private final HouseholdSizeCounter householdSizeCounter;
94	
95	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
96	
97	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
98	
99	    private final OwnerAuditLogger ownerAuditLogger;
100	
101	    private final CustomerCodeDeduplicator customerCodeDeduplicator;
102	
103	    private final IdempotentOwnerCreationStore idempotentOwnerCreationStore;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper,
109	                                 HouseholdDuplicateValidator householdDuplicateValidator,
110	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
111	                                 NamesakeCounter namesakeCounter,
112	                                 HouseholdSizeCounter householdSizeCounter,
113	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
114	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
115	                                 OwnerAuditLogger ownerAuditLogger,
116	                                 CustomerCodeDeduplicator customerCodeDeduplicator,
117	                                 IdempotentOwnerCreationStore idempotentOwnerCreationStore) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	        this.householdDuplicateValidator = householdDuplicateValidator;
123	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
124	        this.namesakeCounter = namesakeCounter;
125	        this.householdSizeCounter = householdSizeCounter;
126	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
127	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
128	        this.ownerAuditLogger = ownerAuditLogger;
129	        this.customerCodeDeduplicator = customerCodeDeduplicator;
130	        this.idempotentOwnerCreationStore = idempotentOwnerCreationStore;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
161	        Optional<Owner> replay = replayForIdempotencyKey(idempotencyKey);
162	        if (replay.isPresent()) {
163	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay.get()), HttpStatus.OK);
164	        }
165	        Owner owner = createOwner(ownerFieldsDto);
166	        rememberForIdempotencyKey(idempotencyKey, owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        HttpHeaders headers = new HttpHeaders();
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
175	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
176	        normalizeAddress(ownerFieldsDto);
177	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
180	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
181	        DisposableEmailDomainValidator.validate(owner.getEmail());
182	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
183	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
184	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
185	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
186	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
187	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
188	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
189	            // An owner sharing a household (same last name and postcode) is otherwise a household
190	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
191	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
192	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
193	                .ifPresent(owner::setPossibleDuplicateOf);
194	        }
195	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
196	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
197	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
198	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
199	        String customerCode = CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
200	        owner.setCustomerCode(this.customerCodeDeduplicator.deduplicate(customerCode));
201	        this.clinicService.saveOwner(owner);
202	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
203	        this.ownerAuditLogger.logCreated(owner);
204	        return owner;
205	    }
206	
207	    /** The owner originally created for this idempotency key, if the key has already been seen. */
208	    private Optional<Owner> replayForIdempotencyKey(String idempotencyKey) {
209	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
210	            return Optional.empty();
211	        }
212	        return this.idempotentOwnerCreationStore.findOwnerId(idempotencyKey)
213	            .map(this.clinicService::findOwnerById);
214	    }
215	
216	    /** Remember the created owner so a repeat with the same idempotency key replays it. */
217	    private void rememberForIdempotencyKey(String idempotencyKey, Owner owner) {
218	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
219	            this.idempotentOwnerCreationStore.remember(idempotencyKey, owner.getId());
220	        }
221	    }
222	
223	    /**
224	     * Normalize the submitted address fields and resolve the effective {@code address}. The
225	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
226	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
227	     * {@code address} input is normalized and kept for backward compatibility.
228	     */
229	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
230	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
231	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
232	        ownerFieldsDto.setAddressLine1(line1);
233	        ownerFieldsDto.setAddressLine2(line2);
234	        if (line1 != null && !line1.isBlank()) {
235	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
236	        } else {
237	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
238	        }
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner == null) {
246	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	        }
248	        currentOwner.setAddress(ownerFieldsDto.getAddress());
249	        currentOwner.setCity(ownerFieldsDto.getCity());
250	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
251	        currentOwner.setLastName(ownerFieldsDto.getLastName());
252	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
253	        this.clinicService.saveOwner(currentOwner);
254	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Transactional
259	    @Override
260	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        this.clinicService.deleteOwner(owner);
266	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner == null) {
274	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	        }
276	        HttpHeaders headers = new HttpHeaders();
277	        Pet pet = petMapper.toPet(petFieldsDto);
278	        owner.setId(ownerId);
279	        pet.setOwner(owner);
280	        pet.getType().setName(null);
281	        this.clinicService.savePet(pet);
282	        PetDto petDto = petMapper.toPetDto(pet);
283	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
284	            .buildAndExpand(pet.getId()).toUri());
285	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
291	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
292	        if (currentOwner != null) {
293	            Pet currentPet = this.clinicService.findPetById(petId);
294	            if (currentPet != null) {
295	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
296	                currentPet.setName(petFieldsDto.getName());
297	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
298	                this.clinicService.savePet(currentPet);
299	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
300	            }
301	        }
302	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
303	    }
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
308	        HttpHeaders headers = new HttpHeaders();
309	        Visit visit = visitMapper.toVisit(visitFieldsDto);
310	        Pet pet = new Pet();
311	        pet.setId(petId);
312	        visit.setPet(pet);
313	        this.clinicService.saveVisit(visit);
314	        VisitDto visitDto = visitMapper.toVisitDto(visit);
315	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
316	            .buildAndExpand(visit.getId()).toUri());
317	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
318	    }
319	
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
324	        Owner owner = this.clinicService.findOwnerById(ownerId);
325	        if (owner != null) {
326	            Pet pet = owner.getPet(petId);
327	            if (pet != null) {
328	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
329	            }
330	        }
331	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
332	    }
333	}
