17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	/**
23	 * Normalizes an owner's address to its canonical storage form. Surrounding whitespace is trimmed,
24	 * internal whitespace runs are collapsed to a single space, and the value is upper-cased. Common
25	 * street-type abbreviations occurring as whole words are expanded ({@code ST -> STREET},
26	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized value is what gets stored, returned and
27	 * compared, so addresses that differ only in spacing, letter case or abbreviation are treated alike.
28	 */
29	public final class AddressNormalizer {
30	
31	    private static final Map<String, String> ABBREVIATIONS = Map.of(
32	        "ST", "STREET",
33	        "RD", "ROAD",
34	        "AVE", "AVENUE");
35	
36	    private AddressNormalizer() {
37	    }
38	
39	    /**
40	     * Returns the canonical form of the submitted address: trimmed, with internal whitespace runs
41	     * collapsed to a single space, upper-cased, and with common street-type abbreviations expanded.
42	     *
43	     * @param address the submitted address, or {@code null} if none was provided
44	     * @return the normalized address, or {@code null} if the input was {@code null}
45	     */
46	    public static String normalize(String address) {
47	        if (address == null) {
48	            return null;
49	        }
50	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
51	        if (collapsed.isEmpty()) {
52	            return collapsed;
53	        }
54	        String[] tokens = collapsed.split(" ");
55	        StringBuilder sb = new StringBuilder(collapsed.length());
56	        for (int i = 0; i < tokens.length; i++) {
57	            if (i > 0) {
58	                sb.append(' ');
59	            }
60	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
61	        }
62	        return sb.toString();
63	    }
64	
65	    /**
66	     * Composes the canonical address from its already-normalized structured lines: the first line,
67	     * with a single space and the second line appended when a second line is present. Blank second
68	     * lines contribute nothing.
69	     *
70	     * @param normalizedLine1 the normalized first address line
71	     * @param normalizedLine2 the normalized second address line, or {@code null}/blank if none
72	     * @return the composed address string
73	     */
74	    public static String compose(String normalizedLine1, String normalizedLine2) {
75	        if (normalizedLine2 == null || normalizedLine2.isBlank()) {
76	            return normalizedLine1;
77	        }
78	        return normalizedLine1 + " " + normalizedLine2;
79	    }
80	}
