19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Set;
22	
23	/**
24	 * Rolls a date forward onto a business day: any Saturday, Sunday, or listed
25	 * public holiday is advanced to the next non-holiday weekday, while an ordinary
26	 * business day is returned unchanged.
27	 */
28	public final class BusinessDayAdjuster {
29	
30	    /** Fixed public holidays that are skipped when rolling to a business day. */
31	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
32	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
33	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
34	            LocalDate.parse("2026-12-28"));
35	
36	    private BusinessDayAdjuster() {
37	    }
38	
39	    /**
40	     * Adjusts the given date to a business day.
41	     *
42	     * @param date the date to adjust
43	     * @return the same date when it is a non-holiday weekday, otherwise the next
44	     *         non-holiday weekday
45	     */
46	    public static LocalDate toBusinessDay(LocalDate date) {
47	        while (isNonBusinessDay(date)) {
48	            date = date.plusDays(1);
49	        }
50	        return date;
51	    }
52	
53	    private static boolean isNonBusinessDay(LocalDate date) {
54	        DayOfWeek day = date.getDayOfWeek();
55	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY
56	                || PUBLIC_HOLIDAYS.contains(date);
57	    }
58	}
