19	import java.util.Locale;
20	
21	/**
22	 * The canonical identity of a household: an owner's last name together with the postcode they live
23	 * at. Two owners belong to the same household when their keys are equal, and therefore derive the
24	 * same stable {@link #idFor(String, String) household id}. The last name is normalized (trimmed,
25	 * internal whitespace runs collapsed to a single space, lower-cased) so values that differ only in
26	 * letter case or spacing match; the postcode is used verbatim. This shared definition keeps
27	 * household matching consistent across every feature that keys off the household.
28	 */
29	public final class HouseholdKey {
30	
31	    private HouseholdKey() {
32	    }
33	
34	    /**
35	     * The canonical key for the household an owner with this last name and postcode belongs to,
36	     * formed as {@code normalizedLastName + '|' + postcode}.
37	     */
38	    public static String of(String lastName, String postcode) {
39	        return normalize(lastName) + "|" + orEmpty(postcode);
40	    }
41	
42	    /**
43	     * The stable identifier for the household an owner with this last name and postcode belongs to:
44	     * the first 12 upper-case hex characters of the SHA-256 digest of its {@link #of(String, String)
45	     * key}. Deterministic, so every owner sharing a last name and postcode derives the same value.
46	     */
47	    public static String idFor(String lastName, String postcode) {
48	        return Sha256.hex(of(lastName, postcode)).substring(0, 12).toUpperCase(Locale.ROOT);
49	    }
50	
51	    private static String normalize(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
56	    }
57	
58	    private static String orEmpty(String value) {
59	        return value == null ? "" : value;
60	    }
61	}
